<?php
require_once "common.php";require_once "../db_connection.php";
if($_SERVER["REQUEST_METHOD"]==="POST"){
 if(!admin_csrf_valid()){header("Location: users.php?error=1");exit;}$id=filter_input(INPUT_POST,"user_id",FILTER_VALIDATE_INT);$action=$_POST["action"]??"";if(!$id){header("Location: users.php?error=1");exit;}
 if($action==="update"){$name=trim($_POST["fullname"]??"");$email=strtolower(trim($_POST["email"]??""));if($name===""||!filter_var($email,FILTER_VALIDATE_EMAIL)){header("Location: users.php?error=1");exit;}$check=mysqli_prepare($conn,"SELECT id FROM users WHERE email=? AND id<>?");mysqli_stmt_bind_param($check,"si",$email,$id);mysqli_stmt_execute($check);$duplicate=mysqli_stmt_get_result($check);$hasDuplicate=mysqli_num_rows($duplicate)>0;mysqli_stmt_close($check);if($hasDuplicate){header("Location: users.php?error=1");exit;}$stmt=mysqli_prepare($conn,"UPDATE users SET fullname=?,email=? WHERE id=?");mysqli_stmt_bind_param($stmt,"ssi",$name,$email,$id);}
 elseif($action==="delete"){$stmt=mysqli_prepare($conn,"DELETE FROM users WHERE id=?");mysqli_stmt_bind_param($stmt,"i",$id);}else{header("Location: users.php?error=1");exit;}
 $ok=mysqli_stmt_execute($stmt);mysqli_stmt_close($stmt);header("Location: users.php?".($ok?"saved=1":"error=1"));exit;
}
$result=mysqli_query($conn,"SELECT users.id,users.fullname,users.email,users.created_at,COUNT(projects.id) AS project_count FROM users LEFT JOIN projects ON projects.user_id=users.id GROUP BY users.id ORDER BY users.created_at DESC,users.id DESC");
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Registered users</title><link rel="stylesheet" href="admin.css"></head><body><header class="admin-header"><a class="admin-brand" href="dashboard.php">International Mobility <span>Administration</span></a><div>Signed in as <?=admin_h($_SESSION["admin_username"])?> · <a href="logout.php">Log out</a></div></header><main class="admin-main"><div class="page-heading"><div><p class="eyebrow">Account management</p><h1>Registered users</h1><p>Update researcher contact details or remove an account.</p></div></div><nav class="admin-tabs"><a href="dashboard.php">Active submissions</a><a class="selected" href="users.php">Registered users</a></nav><?php if(isset($_GET["saved"])):?><p class="notice">User changes saved.</p><?php elseif(isset($_GET["error"])):?><p class="alert">Could not save. Check that the email is valid and unique.</p><?php endif;?>
<section class="table-card"><div class="table-scroll"><table><thead><tr><th>Researcher</th><th>Email</th><th>Registered</th><th>Projects</th><th>Manage account</th></tr></thead><tbody><?php if($result&&mysqli_num_rows($result)):while($u=mysqli_fetch_assoc($result)):?><tr><td><strong><?=admin_h($u["fullname"])?></strong></td><td><a class="mail-link" href="mailto:<?=admin_h($u["email"])?>"><?=admin_h($u["email"])?></a></td><td><?=admin_h(date("d M Y",strtotime($u["created_at"])))?></td><td><?=(int)$u["project_count"]?></td><td><form class="user-edit-form" method="post"><input type="hidden" name="csrf_token" value="<?=admin_h($_SESSION["csrf_token"])?>"><input type="hidden" name="user_id" value="<?=(int)$u["id"]?>"><input type="hidden" name="action" value="update"><label class="visually-hidden" for="name-<?=(int)$u["id"]?>">Name</label><input id="name-<?=(int)$u["id"]?>" name="fullname" required value="<?=admin_h($u["fullname"])?>"><label class="visually-hidden" for="email-<?=(int)$u["id"]?>">Email</label><input id="email-<?=(int)$u["id"]?>" name="email" type="email" required value="<?=admin_h($u["email"])?>"><button class="button button-primary">Save</button></form><form class="delete-user-form" method="post" onsubmit="return confirm('Delete this user and all project submissions? This cannot be undone.');"><input type="hidden" name="csrf_token" value="<?=admin_h($_SESSION["csrf_token"])?>"><input type="hidden" name="user_id" value="<?=(int)$u["id"]?>"><input type="hidden" name="action" value="delete"><button class="button button-danger">Delete account</button></form></td></tr><?php endwhile;else:?><tr><td colspan="5" class="empty-state">No registered users found.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>
